function cleanStr(str) {
  if (!str) return '';
  return str.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

function getEffectiveAllowedCourses(student) {
  if (!student) return ['bootcamp-portugues-cero'];
  const n = (student.name || student.n || '').toLowerCase();
  const u = (student.shortName || student.u || '').toLowerCase();
  if (n.includes('melanie almeyda') || u.includes('melanie almeyda') || (n.includes('valeria') && n.includes('valenzuela')) || (u.includes('valeria') && u.includes('valenzuela'))) {
    return [
      'bootcamp-portugues-cero',
      'bootcamp-portugues-basico2',
      'bootcamp-ingles-cero',
      'club-ingles-a2',
      'bootcamp-master-classes'
    ];
  }
  if (isDocentePatricia(student)) {
    return ['bootcamp-portugues-cero', 'bootcamp-portugues-basico2'];
  }
  if (Array.isArray(student.courses) && student.courses.length > 0) {
    return student.courses;
  }
  if (Array.isArray(student.allowedCourses) && student.allowedCourses.length > 0) {
    return student.allowedCourses;
  }
  return ['bootcamp-portugues-cero'];
}

function isDocentePatricia(student) {
  if (!student) return false;
  const name = (student.n || student.name || '').toLowerCase();
  const username = (student.u || student.shortName || '').toLowerCase();
  const email = (student.e || student.email || '').toLowerCase();
  const role = (student.role || '').toLowerCase();
  const pass = (student.passportNo || '');

  if (pass === 'PM-DOC-001' || pass === 'PM-DOCENTE-PATRICIA') return true;
  if (role.includes('docente oficial') || role.includes('profesora oficial')) return true;
  if (name === 'docente patricia' || username === 'docente patricia' || name === 'docentepatricia' || username === 'docentepatricia') return true;
  if (email.includes('docentepatricia')) return true;

  return false;
}

function authenticateParticipant(usernameInput, passwordInput) {
  if (!usernameInput || !passwordInput) {
    return {
      success: false,
      message: 'Por favor ingresa tu usuario y contraseña.'
    };
  }

  const uClean = cleanStr(usernameInput);
  const pClean = cleanStr(passwordInput);

  if (uClean.length < 2) {
    return {
      success: false,
      message: 'El usuario debe tener al menos 2 caracteres.'
    };
  }

  const match = STUDENTS_DATABASE.find(st => {
    const dniClean = st.dni ? cleanStr(st.dni) : '';
    const pRecord = st.p ? cleanStr(st.p) : '';
    const uRecord = cleanStr(st.u);
    const nRecord = cleanStr(st.n);
    const eRecord = cleanStr(st.e);

    // Contraseña válida:
    // A) Primer nombre y primer apellido (uRecord) -> Opción 1
    // B) Nombre completo (nRecord)
    // C) Contraseña registrada (pRecord)
    // D) DNI registrado (dniClean) -> Opción 2
    // E) Palabra clave coincidente
    const matchesPassword = (pClean === uRecord) || 
                            (pClean === nRecord) || 
                            (pRecord && pClean === pRecord) || 
                            (dniClean && pClean === dniClean) || 
                            (st.k && st.k.some(kw => cleanStr(kw) === pClean));

    // Usuario válido:
    // A) Primer nombre y primer apellido (uRecord)
    // B) Nombre completo (nRecord)
    // C) DNI registrado (dniClean)
    // D) Email (eRecord)
    // E) Palabras clave (st.k)
    const matchesUser = (uClean === uRecord) || 
                        (uClean === nRecord) || 
                        (dniClean && uClean === dniClean) || 
                        (uClean === eRecord) || 
                        (st.k && st.k.some(kw => cleanStr(kw) === uClean));

    if (matchesUser && matchesPassword) return true;
    if (dniClean && uClean === dniClean && pClean === dniClean) return true;
    if ((uClean === uRecord || uClean === nRecord) && uClean === pClean) return true;
    if (dniClean && pClean === dniClean) {
      if (st.k && st.k.some(kw => cleanStr(kw).includes(uClean) || uClean.includes(cleanStr(kw)))) return true;
    }
    if (pClean === uRecord || pClean === nRecord) {
      if (st.k && st.k.some(kw => cleanStr(kw).includes(uClean) || uClean.includes(cleanStr(kw)))) return true;
    }
    return false;
  });

  if (match) {
    const studentCourses = match.courses || ['bootcamp-portugues-cero'];
    const studentRole = match.role || 'Estudiante Inscrito';

    return {
      success: true,
      student: {
        name: match.n,
        shortName: match.u,
        email: match.e || `${cleanStr(match.u)}@estudiante.polyglotmap.com`,
        passportNo: match.passportNo || (match.dni ? `DNI-${match.dni}` : `PM-${cleanStr(match.u).slice(0, 8).toUpperCase()}`),
        role: studentRole,
        allowedCourses: studentCourses,
        courses: studentCourses,
        isDocente: isDocentePatricia(match)
      }
    };
  }

  return {
    success: false,
    message: 'Credenciales no encontradas. Verifica tu Nombre y Apellido (Opción 1) o tu DNI (Opción 2).'
  };
}

if (typeof window !== 'undefined') {
  window.STUDENTS_DATABASE = STUDENTS_DATABASE;
  window.authenticateParticipant = authenticateParticipant;
  window.getEffectiveAllowedCourses = getEffectiveAllowedCourses;
  window.isDocentePatricia = isDocentePatricia;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    STUDENTS_DATABASE,
    authenticateParticipant,
    getEffectiveAllowedCourses,
    isDocentePatricia,
    cleanStr
  };
}
